INSERT INTO `tourinfo` (`title`, `htmlDescription`, `ID`, `URL`) VALUES
('Apna Punjab With Himachal – Private Tour', '<div class=\"gdlr-core-text-box-item gdlr-core-item-pdlr gdlr-core-item-pdb gdlr-core-left-align matt\" style=\"padding-bottom: 41px ;\"><div class=\"gdlr-core-text-box-item-content\" style=\"text-transform: none ;\"><h2>Departure city: Kolkata.</h2>\r\n<h3>Destinations Covered</h3>\r\n<h4></h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Palampur (2 nights)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Amritsar (2 nights)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Hosiyarpur (2 nights)&nbsp;</span></li>\r\n</ul>\r\n<h4>Tour inclusions</h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Accommodation on twin sharing basis in hotels mentioned or similar.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">06 Breakfast – 06 Dinner – 02 Lunch</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">01 Tibetan Food Experience</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">01 Enjoy Punjabi Food Experience at Punjabi Farm house.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">01 Parasada (Guru ka Langar At Golden Temple)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">01 Live Barbeque &amp; Bonfire By The River At Gaj Retreat</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Tea tasting Session in Tea Gardens at Palampur</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Travel Insurance – Travel Insurance (for age below 69yrs)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Transfers &amp; Sightseeing by AC Car.&nbsp;</span></li>\r\n</ul>\r\n<h4>Tour exclusions</h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Additional / personal use of vehicle</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any personal expenses, room service &amp; special orders, mineral waters, beverages, porterage , tips, phone calls, laundry etc</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any extra excursions or sightseeing apart from the above specified itinerary</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Camera fees,</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any incidental and other expenses which are not specified in the inclusions</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Govt service tax (GST) as per prevailing rates.&nbsp;</span></li>\r\n</ul>\r\n<h4>Itinerary</h4>\r\n<h4><b>Day 1 – Arrival in Chandigarh, Palampur&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing during the journey&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 2 – Palampur visit&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing and excursion of the locality&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\r\n</ul>\r\n<h4><b>Day 3 – Palampur to Amritsar&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Enroute Visit Punjab Village Farm&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Attend Attari border ceremony&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\r\n</ul>\r\n<h4><b>Day 4 – Amritsar visit&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Amritsar Local City Tour&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Visit Gobindgarh Fort&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Visit Golden Temple And&nbsp; Take a Guru ka Langar&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Visit Jallianwala Bagh&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Visit Shri Durgiana temple&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 5 – Amritsar to Hoshiarpur&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Visit Bhakra-Nangal Dam &amp; Gobind Sagar Lake&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 6 – Hoshiarpur&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Dairy Farm&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Potter’s Wheel&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Tractor &amp; Trolley Ride In The Fields&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Bullock Cart Ride&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Sundowners&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Live Barbeque &amp; Bonfire By The River&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Star Gazing&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Glamping By The River&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 7 – Departure from Hoshiarpur, Chandigarh&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Morning at leisure&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast included</span></li>\r\n</ul>\r\n</div></div>', 1, 'apna-punjab-with-himachal-private-tour'),
('Customizable Himachal (Shimla – Manali – Chandigarh)', '<div class=\"gdlr-core-text-box-item gdlr-core-item-pdlr gdlr-core-item-pdb gdlr-core-left-align matt\" style=\"padding-bottom: 41px ;\"><div class=\"gdlr-core-text-box-item-content\" style=\"text-transform: none ;\"><h2>Departure city: Kolkata.</h2>\n<h3>Destinations Covered</h3>\n<p>&nbsp;</p>\n<ul>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Chandigarh (0 night)&nbsp;</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Shimla (2 nights)&nbsp;</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Manali (3 nights)&nbsp;</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Chandigarh (1 night)&nbsp;</span></li>\n</ul>\n<h4>Tour inclusions</h4>\n<ul>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Accommodation in the mentioned or similar hotels.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Daily breakfast &amp; Dinner at all places. Rest of the Meals, if any, as per the above.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Per Day 500 Ml Per Water Bottle</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All transfers and sightseeing by AC Vehicle. (Please note that AC will be switched off during hills )</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All toll taxes, parking charges, driver allowances.&nbsp;</span></li>\n</ul>\n<h4><b>Tour exclusions&nbsp;</b></h4>\n<ul>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any Air or Rail fare.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any other meal not mentioned in price includes.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Tips &amp; PorterageAny monument entrance fees, camera fees, guide charges.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any expenses of personal nature.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">GST @ Current Rate&nbsp;</span></li>\n</ul>\n<h4><b>Itinerary&nbsp;</b></h4>\n<h4><b>Day 1 – Ceck-in to Shimla hotel&nbsp;</b></h4>\n<ul>\n<li><span style=\"font-weight: 400;\">Evening leisure&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Sightseeing during the journey&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Dinner included&nbsp;</span></li>\n</ul>\n<h4><b>Day 2 – Morning to noon sightseeing&nbsp;</b></h4>\n<ul>\n<li><span style=\"font-weight: 400;\">Shimla Local with Kufri Jakhu temple&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Naldehra&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Kufri&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Visit Kufri Fun Campus&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Evening Shimla Mall Road Visit&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\n</ul>\n<h4><b>Day 3 – Check-in to Manali hotel&nbsp;</b></h4>\n<ul>\n<li><span style=\"font-weight: 400;\">Noon at leisure&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Evening at leisure&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\n</ul>\n<h4><b>Day 4 – Manali Local City Tour</b></h4>\n<ul>\n<li><span style=\"font-weight: 400;\">Naggar Hidimba Temple</span></li>\n<li><span style=\"font-weight: 400;\">Manu Mandir&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Vashisth Kund and Naggar Art Gallery&nbsp;&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Evening Shimla Mall Road Visit&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\n</ul>\n<h4><b>Day 5 – Morning to noon sightseeing&nbsp;</b></h4>\n<ul>\n<li style=\"list-style-type: none;\">\n<ul>\n<li style=\"list-style-type: none;\">\n<ul>\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">Full day Excursion Solang Valley With Gulaba Snow Point&nbsp;</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">Full day Excursion to Solang Valley With Gulaba Snow Point&nbsp;</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n<h4><b>Day 6 – Check-in to Chandigarh hotel&nbsp;</b></h4>\n<ul>\n<li><span style=\"font-weight: 400;\">Evening at leisure&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\n</ul>\n<h4><b>Day 7 – Airport transfers&nbsp;</b></h4>\n<ul>\n<li><span style=\"font-weight: 400;\">Morning at leisure&nbsp;</span></li>\n<li><span style=\"font-weight: 400;\">Breakfast included&nbsp;</span></li>\n</ul>\n</div></div>', 2, 'customizable-himachal-shimla-manali-chandigarh'),
('Nubra Valley Trails with Leh and Pangong', '<div class=\"gdlr-core-text-box-item gdlr-core-item-pdlr gdlr-core-item-pdb gdlr-core-left-align matt\" style=\"padding-bottom: 41px ;\"><div class=\"gdlr-core-text-box-item-content\" style=\"text-transform: none ;\"><h2>Departure city: Kolkata.&nbsp;</h2>\r\n<h3>Destinations Covered&nbsp;</h3>\r\n<h4>Tour inclusions</h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Accommodation in Twin/Double sharing basis in Starting Room category at each place</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">06 breakfasts and 06 dinners</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Transportation by NAC Xylo / Scorpio / Innova (1 to 6 pax) &amp; Non Ac Tempo Trv (7 to 12 pax) (as per availability) for arrival / departure transfers, sightseeing as per the itinerary.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Assistance at the airport while arriving and departing.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Oxygen Cylinder in each vehicle while travelling to Nubra/ Pangong Only</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Travel Insurance (for age below 69yrs).<br></span><strong>Mics. charges are inclusive like</strong></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Ladakh Royalty Fee.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Inner-line permits</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Potareges at hotel and airport</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All applicable luxury/ road taxes&nbsp;</span></li>\r\n</ul>\r\n<h4>Tour exclusions&nbsp;</h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Airfares and train fare.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any monastery entrance fees, Any Joy ride or rafting.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Medical expenses (apart from first aid) and insurance of any kind.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Tips, laundry, liquors, wines, mineral water, telephone charges, camera fee and items of personal nature.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Transportation is not on disposal basis. It is strictly as per the programme, any extra running will be charges extra.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any expenses arising out of unforeseen circumstances like flight delay / cancellation / hike in fare, strike or any other natural calamities or any emergency evacuation expenses.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any other item not mentioned in the cost includes section.<br></span><strong>Note: Supplement for English Speaking Local Guide (optional): Rs. 3000.00 per day.<br></strong><strong>On Tour Activity supplement charges:</strong></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Zipline Ride at highest altitude INR 2000/- per person.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">ATV Ride on Hunder Sand dunes @ INR 1500/- per person per ride.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Double Hump Camel Ride @ INR 650/- per person for half an hour ride.&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Itinerary&nbsp;</b></h4>\r\n<h4>Day 1 – Arrival at Leh&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing during the journey&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4>Day 2 – Monastery tour and Leh sightseeing&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Thiksey Gompa&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Shey Palace And Gompa&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Donkey Sanctuary&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Leh&nbsp; Palace&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Shanti Stupa (Japanese Peace Pagoda)&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;&nbsp;</span></li>\r\n</ul>\r\n<h4>Day 3 – Leh to Nubra via Khardungla Pass&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Khardungla Pass&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Deskit Village&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Deskit Gompa&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Hundar Village&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;&nbsp;</span></li>\r\n</ul>\r\n<h4>Day 4 – Nubra To Turtuk Excursion&nbsp;&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Nubra To Turtuk Excursion&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\r\n</ul>\r\n<h4>Day 5 – Nubra Sumur, Ensa Monastery &amp; Yarab Tso&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing and excursion of the locality&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\r\n</ul>\r\n<h4>Day 6 – Nubra To Pangong Lake Day Excursion&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing and excursion of the locality&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\r\n</ul>\r\n<h4>Day 7 – Airport Departure&nbsp;</h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing during the journey&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast included&nbsp;</span></li>\r\n</ul>\r\n</div></div>', 3, 'nubra-valley-trails-with-leh-and-pangong'),
('Marvellous Ladakh with Turtuk', '<div class=\"gdlr-core-text-box-item gdlr-core-item-pdlr gdlr-core-item-pdb gdlr-core-left-align matt\" style=\"padding-bottom: 41px ;\"><div class=\"gdlr-core-text-box-item-content\" style=\"text-transform: none ;\"><h2>Departure city: Kolkata.</h2>\r\n<h3>Destinations Covered</h3>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">&nbsp;Leh (2 nights)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Nubra Valley (1 night)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Pangong (1 night)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Leh (1 night)</span></li>\r\n</ul>\r\n<h4>Tour inclusions</h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Accommodation in Twin/Double sharing basis in Starting Room category at each place</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">07 breakfasts and 07 dinners</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Transportation by NAC Xylo / Scorpio / Innova (1 to 6 pax) &amp; Non Ac Tempo Trv (7 to 12 pax) (as per availability) for arrival / departure transfers, sightseeing as per the itinerary.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Assistance at the airport while arriving and departing.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Oxygen Cylinder in each vehicle while travelling to Nubra/ Pangong only.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Travel Insurance (for age below 69yrs).<br></span><strong>Misc. charges are inclusive like:</strong></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Ladakh Royalty Fee</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Inner-line permits</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Portages at hotel and airport</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All applicable luxury/ road taxes&nbsp;</span></li>\r\n</ul>\r\n<h4>Tour exclusions</h4>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">GST will be applicable as per prevailing rates.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Airfares trainfare.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any monastery entrance fees, Any Joy ride or rafting.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Medical expenses (apart from first aid) and insurance of any kind.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Tips, laundry, liquors, wines, mineral water, telephone charges, camera fee and items of personal nature.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Transportation is not on disposal basis. It is strictly as per the programme, any extra running will be charges extra.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any expenses arising out of unforeseen circumstances like flight delay / cancellation / hike in fare, strike or any other natural calamities or any emergency evacuation expenses.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any other item not mentioned in the cost includes section.<br></span><strong>Note: Supplement for English Speaking Local Guide (optional): Rs. 3000.00 per day.&nbsp;</strong></li>\r\n</ul>\r\n<h4>Itinerary</h4>\r\n<h4><b>Day 1 – Arrival at Leh&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing during the journey&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Dinner included</span></li>\r\n</ul>\r\n<h4><b>Day 2 – Sham Valley Tour&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Hall Of Fame, Magnetic Hill, Gurudwara Pathar Sahib &amp; Sangam&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 3 – Leh to Khardung La to Nubra Valley&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing and excursion of the locality&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 4 – Nubra Valley&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Excursion To Turtuk&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 5 – Nubra to Pangong&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing and excursion of the locality&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included</span></li>\r\n</ul>\r\n<h4><b>Day 6 – Pangong to Leh&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing and excursion of the locality&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast and dinner included&nbsp;</span></li>\r\n</ul>\r\n<h4><b>Day 7 – Departure from Leh&nbsp;</b></h4>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Sightseeing during the journey&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Breakfast included&nbsp;</span></li>\r\n</ul>\r\n</div></div>', 4, 'marvellous-ladakh-with-turtuk'),
